    .reg .b32   %r<12>;
    .reg .b64   %rd<12>;
    .reg .f32   %f<40>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r6, [numel];

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;
    shl.b32 %r5, %r4, 2;

    add.u32 %r7, %r5, 3;
    setp.lt.u32 %p1, %r7, %r6;
    @!%p1 bra GELU_TAIL;

    mul.wide.u32 %rd3, %r5, 4;
    add.s64 %rd4, %rd1, %rd3;
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];

    mul.f32 %f5, %f1, %f1;
    fma.rn.f32 %f6, %f5, 0.044715, 1.0;
    mul.f32 %f7, %f6, %f1;
    mul.f32 %f8, %f7, 0.7978845608028654;
    mul.f32 %f9, %f8, 2.885390081777927;
    ex2.approx.f32 %f10, %f9;
    add.f32 %f11, %f10, 1.0;
    rcp.rn.f32 %f12, %f11;
    mul.f32 %f13, %f1, %f12;
    sub.f32 %f1, %f1, %f13;

