    mul.f32 %f7, %f6, %f2;
    mul.f32 %f8, %f7, 0.7978845608028654;
    mul.f32 %f9, %f8, 2.885390081777927;
    ex2.approx.f32 %f10, %f9;
    add.f32 %f11, %f10, 1.0;
    rcp.rn.f32 %f12, %f11;
    mul.f32 %f13, %f2, %f12;
    sub.f32 %f2, %f2, %f13;

    mul.f32 %f5, %f3, %f3;
    fma.rn.f32 %f6, %f5, 0.044715, 1.0;
    mul.f32 %f7, %f6, %f3;
    mul.f32 %f8, %f7, 0.7978845608028654;
    mul.f32 %f9, %f8, 2.885390081777927;
    ex2.approx.f32 %f10, %f9;
    add.f32 %f11, %f10, 1.0;
    rcp.rn.f32 %f12, %f11;
    mul.f32 %f13, %f3, %f12;
    sub.f32 %f3, %f3, %f13;

    mul.f32 %f5, %f4, %f4;
    fma.rn.f32 %f6, %f5, 0.044715, 1.0;
    mul.f32 %f7, %f6, %f4;
    mul.f32 %f8, %f7, 0.7978845608028654;
    mul.f32 %f9, %f8, 2.885390081777927;
    ex2.approx.f32 %f10, %f9;
    add.f32 %f11, %f10, 1.0;
    rcp.rn.f32 %f12, %f11;
    mul.f32 %f13, %f4, %f12;
    sub.f32 %f4, %f4, %f13;

    add.s64 %rd5, %rd2, %rd3;
    st.global.v4.f32 [%rd5], {%f1, %f2, %f3, %f4};
    bra GELU_DONE;

GELU_TAIL:
    setp.lt.u32 %p2, %r5, %r6;
    @!%p2 bra GELU_DONE;
    mul.wide.u32 %rd6, %r5, 4;
    add.s64 %rd7, %rd1, %rd6;
    ld.global.f32 %f20, [%rd7];
    mul.f32 %f21, %f20, %f20;
    fma.rn.f32 %f22, %f21, 0.044715, 1.0;
    mul.f32 %f23, %f22, %f20;
    mul.f32 %f24, %f23, 0.7978845608028654;
    mul.f32 %f25, %f24, 2.885390081777927;
    ex2.approx.f32 %f26, %f25;
    add.f32 %f27, %f26, 1.0;
    rcp.rn.f32 %f28, %f27;
    mul.f32 %f29, %f20, %f28;
    sub.f32 %f20, %f20, %f29;
    add.s64 %rd8, %rd2, %rd6;
    st.global.f32 [%rd8], %f20;
    add.u32 %r5, %r5, 1;
    bra GELU_TAIL;

GELU_DONE:
    ret;
