def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("gelu_forward_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        out = torch.empty_like(x)
        n = x.numel()
        if n == 0:
            return out
        threads = (n + 3) // 4
        grid_x = (threads + 255) // 256
        _get_ptx_module().launch(
            "gelu_forward_kernel",
            grid=(grid_x, 1, 1),
            block=(256, 1, 1),
            arguments=[x, out, u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

